  ('stage1', 'authority_friend', 'authority_friend', 'null', '', '', 0, 'dial', NULL, NULL, '{"l":"專業權威","q":"你說話更像醫生／顧問，還是像懂行的朋友？","le":"像主診醫師：用詞精準、保持距離、給明確結論。","re":"像懂行的朋友：會問近況，用日常語言。","lw":"代價：客人可能覺得冷、有距離。適合需要權威背書的領域（醫療、金融）。","rw":"代價：可能被質疑不夠專業。適合怕被教訓、想被陪伴的領域（生活、保養）。"}'::jsonb),
  ('stage1', 'precise_warm', 'precise_warm', 'null', '', '', 0, 'dial', NULL, NULL, '{"l":"精準理性","q":"打動客人靠數據與邏輯，還是靠感受與故事？","le":"用數字、對比、證據說服。","re":"用情境、故事、共鳴說服。","lw":"代價：容易顯得無趣、難建立情感連結。","rw":"代價：缺乏證據時會被覺得空泛。"}'::jsonb),
  ('stage1', 'quiet_bold', 'quiet_bold', 'null', '', '', 0, 'dial', NULL, NULL, '{"l":"低調克制","q":"品牌出現時，是安靜融入還是主動搶眼？","le":"留白多、色彩少、不大聲說話。","re":"色彩強、版面大膽、態度明確。","lw":"代價：不易被記住，需靠品質累積口碑。","rw":"代價：容易被厭倦，且不適合嚴肅或私密議題。"}'::jsonb),
  ('stage1', 'trad_modern', 'trad_modern', 'null', '', '', 0, 'dial', NULL, NULL, '{"l":"傳統承載","q":"你的價值來自傳承，還是來自新方法？","le":"強調歷史、工藝、經過時間驗證。","re":"強調新方法、新技術、重新定義。","lw":"代價：可能被覺得老派。","rw":"代價：缺乏歷史時需要別的方式建立信任。"}'::jsonb),
  ('stage1', 'premium_access', 'premium_access', 'null', '', '', 0, 'dial', NULL, NULL, '{"l":"高端稀有","q":"你想讓人覺得『難得』，還是『誰都用得起』？","le":"限量、精選、價格較高、門檻較高。","re":"價格親民、隨時可得、容易上手。","lw":"代價：客群較小，需要極高的一致性。","rw":"代價：利潤薄、品牌容易被視為廉價。"}'::jsonb),
  ('stage1', 'simple_deep', 'simple_deep', 'null', '', '', 0, 'dial', NULL, NULL, '{"l":"簡單易上手","q":"客人第一次接觸，你要讓他覺得輕鬆，還是覺得你很懂？","le":"一句話講完，三步就能開始。","re":"提供細節、選項、進階內容。","lw":"代價：專業客人可能覺得不夠深。","rw":"代價：新手可能被嚇跑。"}'::jsonb),
  ('stage1', 'calm_energy', 'calm_energy', 'null', '', '', 0, 'dial', NULL, NULL, '{"l":"療癒安靜","q":"客人接觸你之後，應該感到放鬆，還是被激勵？","le":"讓人放慢、安心、被照顧。","re":"讓人行動、挑戰、變得更好。","lw":"代價：不適合需要推動行為改變的場景。","rw":"代價：不適合需要安撫情緒的場景。"}'::jsonb),
  ('stage1', 'local_global', 'local_global', 'null', '', '', 0, 'dial', NULL, NULL, '{"l":"在地親切","q":"你想像是『我們這裡的品牌』，還是『世界級的品牌』？","le":"用在地語言、習俗與場景溝通。","re":"用國際通用的語言與標準。","lw":"代價：擴展到其他市場時需要重新定位。","rw":"代價：可能失去在地人的親切感。"}'::jsonb)
