values
  ('stage4b', 'gradType', 'gt_none', '不使用漸變', '全部使用實色。', '類型', 0, 'category', NULL, NULL, '{"fit":"最安全、最易印刷與無障礙；極簡、資訊型、單色印刷品牌。","avoid":"缺少光感與深度，需靠形狀、紋理或攝影補足。","pair":"配實色填色與紋理。","t":["quiet","modern"],"sw":"#E4E7EC","conf":[],"cost":0,"minLine":0,"minType":0,"grad":null,"vec":false,"shift":false,"note":""}'::jsonb),
  ('stage4b', 'gradType', 'gt_linear', '線性漸變', '沿一個方向由一色漸變為另一色。', '類型', 1, 'category', NULL, NULL, '{"fit":"背景、按鈕、卡片、封面；最通用。","avoid":"文字覆蓋時須檢查最差位置；紫藍漸變易過時。","pair":"配形狀與留白；全系統統一角度。","t":["modern","digital"],"sw":"linear-gradient(135deg,#7FD6FF,#1E4FD8)","conf":[],"cost":0,"minLine":0,"minType":0,"grad":null,"vec":false,"shift":false,"note":""}'::jsonb),
  ('stage4b', 'gradType', 'gt_radial', '徑向光暈', '由中心向外擴散，像光源。', '類型', 2, 'category', NULL, NULL, '{"fit":"聚焦主體、英雄區、柔和光感。","avoid":"過度使用變成『光暈背景』，易顯過時；中心與邊緣的對比不同。","pair":"配攝影與暗色背景。","t":["soft","digital","halo"],"sw":"radial-gradient(circle at 50% 40%,#FFFFFF,#B8C7F5)","conf":[],"cost":0,"minLine":0,"minType":0,"grad":null,"vec":false,"shift":false,"note":""}'::jsonb),
  ('stage4b', 'gradType', 'gt_conic', '錐形／角度漸變', '繞中心一圈變色。', '類型', 3, 'category', NULL, NULL, '{"fit":"圖示底、頭像框、載入環。","avoid":"印刷難重現；易顯炫技。","pair":"配圓形與環形。","t":["loud","digital"],"sw":"conic-gradient(from 0deg,#FF2BD6,#00F0FF,#B6FF00,#FF2BD6)","conf":[],"cost":0,"minLine":0,"minType":0,"grad":null,"vec":false,"shift":false,"note":""}'::jsonb),
  ('stage4b', 'gradType', 'gt_mesh', '網格／彌散漸變（Mesh）', '多個色團柔和混合。', '類型', 4, 'category', NULL, NULL, '{"fit":"形象背景、封面、柔和氣氛。","avoid":"檔案大；易出現色帶；印刷與單色版難重現；易過時。","pair":"配極淡噪點抑制色帶。","t":["soft","digital","dated","halo"],"sw":"radial-gradient(circle at 20% 30%,#F9C6D8,transparent 55%),radial-gradient(circle at 80% 70%,#C6D8F9,transparent 55%),#FBF9F4","conf":[],"cost":0,"minLine":0,"minType":0,"grad":null,"vec":false,"shift":false,"note":""}'::jsonb),
  ('stage4b', 'gradType', 'gt_metal', '金屬／光澤漸變', '多段明暗模擬金屬反光。', '類型', 5, 'category', NULL, NULL, '{"fit":"高端、金銀質感（螢幕模擬）。","avoid":"易顯俗豔；與實際燙金／金屬油墨不是同一回事，不可冒充；Stage 2 若禁過度金屬須避免。","pair":"配黑金色彩；實物須用燙箔或金屬油墨。","t":["luxe","flashy","loud"],"sw":"linear-gradient(135deg,#8C6B2C,#F2E4B8 45%,#C9A24A 60%,#6B511F)","conf":[],"cost":0,"minLine":0,"minType":0,"grad":null,"vec":false,"shift":false,"note":""}'::jsonb),
  ('stage4b', 'gradType', 'gt_map', '雙色調映射（Gradient map）', '把照片明暗映射到兩三個顏色。', '類型', 6, 'category', NULL, NULL, '{"fit":"系列影像統一、活動封面。","avoid":"降低膚色與產品真實度；健康宣稱類影像要小心。","pair":"配雙色調攝影處理（4A）。","t":["bold","modern"],"sw":"linear-gradient(135deg,#1B2A6B,#F5C400)","conf":[],"cost":0,"minLine":0,"minType":0,"grad":null,"vec":false,"shift":false,"note":""}'::jsonb),
  ('stage4b', 'gradUse', 'gu_bg', '背景', '頁面或區塊背景。', '用途', 0, 'category', NULL, NULL, '{"fit":"最常見、風險較低。","avoid":"文字覆蓋位置的最差對比。","pair":"配遮罩或純色文字底。","t":[],"sw":"","conf":[],"cost":0,"minLine":0,"minType":0,"grad":null,"vec":false,"shift":false,"note":""}'::jsonb),
  ('stage4b', 'gradUse', 'gu_btn', '按鈕', '主要行動按鈕填色。', '用途', 1, 'category', NULL, NULL, '{"fit":"強調行動。","avoid":"狀態（懸停、按下、禁用）要重新定義；文字對比逐點檢查。","pair":"配實色備援。","t":[],"sw":"","conf":[],"cost":0,"minLine":0,"minType":0,"grad":null,"vec":false,"shift":false,"note":""}'::jsonb),
