  ('stage4b', 'gradUse', 'gu_chart', '資料圖表', '圖表色帶與熱圖。', '用途', 3, 'category', NULL, NULL, '{"fit":"連續資料。","avoid":"不可只靠漸變表意；須有數值標示與色盲友善。","pair":"配 4E 圖表規則。","t":[],"sw":"","conf":[],"cost":0,"minLine":0,"minType":0,"grad":null,"vec":false,"shift":false,"note":""}'::jsonb),
  ('stage4b', 'gradUse', 'gu_scrim', '照片遮罩（Scrim）', '在照片上加漸變，讓文字可讀。', '用途', 4, 'category', NULL, NULL, '{"fit":"文字壓照片。","avoid":"遮罩強度要夠；照片最亮處仍須測。","pair":"配文字在遮罩底部或單側。","t":[],"sw":"","conf":[],"cost":0,"minLine":0,"minType":0,"grad":null,"vec":false,"shift":false,"note":""}'::jsonb),
