-- 品牌引導 12 stage 選項庫種子（由 reference options.js 一次性轉換）。
-- 選項欄位：category（多選）、dim（單選）、dial（刻度）。
-- 文字欄位（TEXTS）不進選項表，寫入 brand_guide_stage.text_fields。

-- ── stage0 ── headx-stage0-business-v2 ────────────────────────────

on conflict (stage, dimension, opt_id) do nothing;

update brand_guide_stage
   set text_fields = '[{"id":"what","label":"我們做什麼","ph":"例：為都市女性提供針灸與中藥調理的診所","help":"用一句日常說話，不用行話。像向朋友介紹那樣。","rows":2},{"id":"who","label":"主要給誰","ph":"例：30–45 歲、長期睡不好的上班族","help":"一個具體的人群，不是『所有人』。","rows":2},{"id":"how","label":"怎麼收錢","ph":"例：預約按次收費，也賣六次療程套票","help":"收入怎麼來。","rows":2},{"id":"calcTicket","label":"平均每次消費（港元）","ph":"例：800","help":"客單價。只填數字。","rows":1},{"id":"calcMargin","label":"毛利率（%）","ph":"例：60","help":"每賣 100 元，扣掉直接成本後剩多少。不知道可留空。","rows":1},{"id":"calcVisits","label":"每位客人每年平均消費幾次","ph":"例：6","help":"一次性客人填 1。","rows":1},{"id":"calcYears","label":"客人平均維持幾年","ph":"例：2","help":"保守估計。","rows":1},{"id":"calcCac","label":"獲得一位新客的平均成本（港元）","ph":"例：300","help":"廣告、折扣、人手時間都算。口碑客可算 0。","rows":1},{"id":"calcFixed","label":"每月固定成本（港元）","ph":"例：60000","help":"租金、薪金、保險、軟件等不隨生意量變的成本。","rows":1},{"id":"calcTarget","label":"每月想賺到的淨利（港元，選填）","ph":"例：20000","help":"用來計算需要多少成交。","rows":1},{"id":"purpose","label":"為什麼做這件事（Why）","ph":"例：希望讓人不再覺得看中醫是麻煩又冰冷的事","help":"不是『賺錢』，是你相信什麼、想改變什麼。","rows":3},{"id":"vision","label":"三至五年後想成為什麼","ph":"例：成為灣區最被信任的女性調理品牌","help":"","rows":2},{"id":"story","label":"起源故事","ph":"例：我曾經長期失眠，跑遍很多地方才找到方法…","help":"真實的起點，最能讓人記住。","rows":3},{"id":"founder","label":"創辦人／團隊背景","ph":"例：註冊中醫師，十年臨床；前設計師","help":"資歷與經驗，是信任的來源。","rows":2},{"id":"partners","label":"主要合作夥伴與供應商","ph":"例：中藥材供應商、保險公司、預約平台","help":"Business Model Canvas 的『關鍵合作夥伴』。","rows":2},{"id":"costs","label":"最主要的成本是什麼","ph":"例：租金、人手、藥材、廣告","help":"Business Model Canvas 的『成本結構』。","rows":2},{"id":"comp1","label":"競爭對手 1","ph":"名稱＋一句話說明他們哪裡好、哪裡不好","help":"可以是直接同行，也可以是『替代方案』。","rows":2},{"id":"comp2","label":"競爭對手 2","ph":"","help":"","rows":2},{"id":"comp3","label":"競爭對手 3","ph":"","help":"","rows":2},{"id":"admire1","label":"欣賞的品牌 1","ph":"名稱＋欣賞什麼（不限行業）","help":"可以完全不同行業。","rows":2},{"id":"admire2","label":"欣賞的品牌 2","ph":"","help":"","rows":2},{"id":"admire3","label":"欣賞的品牌 3","ph":"","help":"","rows":2},{"id":"mustHave","label":"一定要做到的事","ph":"例：一定要有註冊醫師親自診治","help":"這是底線。","rows":2},{"id":"dealBreaker","label":"絕對不接受的事","ph":"例：不用恐嚇式宣傳","help":"寫下之後可成為 Anti-Persona 的依據。","rows":2},{"id":"existingName","label":"現有名稱（如有）","ph":"","help":"","rows":1},{"id":"nameCandidates","label":"候選名稱（每行一個）","ph":"","help":"","rows":3},{"id":"legalZh","label":"公司註冊名稱（中文）","ph":"","help":"與商業登記證一致。","rows":1},{"id":"legalEn","label":"公司註冊名稱（英文）","ph":"","help":"","rows":1},{"id":"trading","label":"營業名稱／店名","ph":"","help":"對外使用的名字。","rows":1},{"id":"address","label":"營業地址","ph":"","help":"","rows":1},{"id":"email","label":"聯絡電郵","ph":"","help":"","rows":1},{"id":"phone","label":"聯絡電話／WhatsApp","ph":"","help":"","rows":1},{"id":"website","label":"網站","ph":"","help":"","rows":1},{"id":"social","label":"社群帳號（每行一個）","ph":"","help":"","rows":2},{"id":"currency","label":"主要貨幣","ph":"HKD","help":"","rows":1},{"id":"timezone","label":"時區","ph":"Asia/Hong_Kong","help":"","rows":1},{"id":"fiscalEnd","label":"財政年度結束日","ph":"例：3 月 31 日 或 12 月 31 日","help":"","rows":1}]'::jsonb
 where stage = 'stage0';

