update brand_guide_stage
   set text_fields = '[{"id":"brandName","label":"品牌名稱（用於標誌）","ph":"例：滿月堂","help":"標誌上會出現的文字；若已匯入 Stage 0 會自動帶入。","rows":1},{"id":"brandNameEn","label":"英文名稱（如有）","ph":"例：Moonic","help":"沒有可留空。","rows":1},{"id":"idBrief","label":"識別任務（一句話）","ph":"例：把一間中醫診所的識別整理成可在網站、包裝與制服一致使用的系統","help":"說清楚這套識別要解決什麼。","rows":2},{"id":"mustKeep","label":"一定要保留","ph":"例：現有的月亮意象與紫藍色","help":"列出不可丟的資產與理由。","rows":2},{"id":"mustAvoid","label":"絕對要避免","ph":"例：像連鎖美容院、像醫院","help":"可參考 Stage 1 的 Anti-Persona。","rows":2},{"id":"logoConcept","label":"標誌的概念與故事","ph":"例：月相代表日夜調理與循環","help":"標誌背後的意念；避免空泛字眼。","rows":3},{"id":"logoNotes","label":"標誌補充說明","ph":"例：中文字標需客製，英文用現成字體微調","help":"製作要求、已知風險與待決事項。","rows":3},{"id":"typeNotes","label":"字體補充說明","ph":"例：標題用襯線強調人味，內文用黑體確保可讀","help":"","rows":3},{"id":"colorNotes","label":"色彩補充說明","ph":"例：紫藍為主色，粉紅與杏色只用於服務標記","help":"","rows":3},{"id":"tmNote","label":"商標與相似度查證備註","ph":"例：已自行搜尋，未見相同標誌；尚未請專業人士確認","help":"只是記錄；不構成法律意見。","rows":2},{"id":"statement","label":"識別宣言（一句話）","ph":"例：安靜而精準，像月光下的診間","help":"一句話說清楚這套識別的選擇與取捨。","rows":3}]'::jsonb
 where stage = 'stage4a';

