   set text_fields = '[{"id":"brandName","label":"品牌名稱","ph":"例：滿月堂","help":"未匯入前階段時請手動填寫。","rows":1},{"id":"c_primary","label":"主色（HEX）","ph":"#2F6BFF","help":"匯入 4A 時自動帶入，可修改。","rows":1},{"id":"c_secondary","label":"輔色（HEX）","ph":"#E4E7EC","help":"","rows":1},{"id":"c_accent","label":"點綴色（HEX）","ph":"#FFC400","help":"","rows":1},{"id":"c_ink","label":"文字色（HEX）","ph":"#111827","help":"","rows":1},{"id":"c_paper","label":"背景色（HEX）","ph":"#FFFFFF","help":"","rows":1},{"id":"g_a","label":"漸變色標 1（HEX）","ph":"#7FD6FF","help":"起點。","rows":1},{"id":"g_b","label":"漸變色標 2（HEX，選填）","ph":"#4A7CF0","help":"中間色；留空只用兩色。","rows":1},{"id":"g_c","label":"漸變色標 3（HEX）","ph":"#1E4FD8","help":"終點。","rows":1},{"id":"g_mid","label":"中間色標位置（%）","ph":"50","help":"預設 50。","rows":1},{"id":"g_angle","label":"角度（度）","ph":"135","help":"線性或錐形的角度。","rows":1},{"id":"g_txt","label":"要放在漸變上的文字色（HEX）","ph":"#FFFFFF","help":"用來取樣檢查對比。","rows":1},{"id":"g_note","label":"漸變用途與限制","ph":"例：只用於首頁英雄區；文字一律放在遮罩上","help":"","rows":2},{"id":"bd_mm","label":"印刷邊框實際線寬（mm，選填）","ph":"0.5","help":"用來檢查工藝最小線寬。","rows":1},{"id":"pt_size","label":"單元大小（px）","ph":"48","help":"無縫單元的邊長。","rows":1},{"id":"pt_motif","label":"母題大小（單元的 %）","ph":"40","help":"母題占單元的比例。","rows":1},{"id":"pt_stroke","label":"線寬（px，線條母題）","ph":"2","help":"線條母題與波浪、斜線、格網。","rows":1},{"id":"pt_rot","label":"旋轉（度）","ph":"0","help":"母題整體旋轉。","rows":1},{"id":"pt_c1","label":"母題顏色（HEX）","ph":"#2F6BFF","help":"留空用主色。","rows":1},{"id":"pt_c2","label":"圖案底色（HEX）","ph":"#FFFFFF","help":"留空用背景色。","rows":1},{"id":"pt_mm","label":"印刷時單元實際大小（mm，選填）","ph":"20","help":"用來換算線寬並檢查工藝最小線寬。","rows":1},{"id":"pf","label":"P3 增強的彩度倍數","ph":"1.1","help":"1.0–1.4；預設 1.1。只是示意。","rows":1},{"id":"st_note","label":"印刷廠／供應商與打樣備註","ph":"例：A 印刷廠；2026-12 打樣；ICC：待提供","help":"記錄廠商、版本、打樣日期、核准者。","rows":3},{"id":"statement","label":"圖形與表面系統一句話（選填，留空自動生成草稿）","ph":"","help":"","rows":3}]'::jsonb
